-- Create "staking_state_heads" table
CREATE TABLE "staking_state_heads" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "block_number" numeric NOT NULL,
  "updated_at" timestamptz NOT NULL,
  PRIMARY KEY ("id")
);
-- Seed the committed head from the staking events already applied, so a resync
-- before the first worker commit cannot write a snapshot older than them
INSERT INTO "staking_state_heads" ("block_number", "updated_at")
SELECT MAX("block_number"), now() FROM "staking_events" HAVING MAX("block_number") IS NOT NULL;
